def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            seen.add((r,c)); pts=[(r,c)]
            for y,x in pts:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); pts.append((a,b))
            if max(x for y,x in pts)-min(x for y,x in pts)>max(y for y,x in pts)-min(y for y,x in pts):
                for y,x in pts: out[y][x]=3
    return out

